const wh = $('Webhook').first().json.body || {};
const accRows = ($('HTTP SELECT accounts').first().json.rows) || [];
const accByPlatform = {};
for (const r of accRows) {
  if (r && r.platform && accByPlatform[r.platform] === undefined) accByPlatform[r.platform] = r.id;
}
const platforms = Array.isArray(wh.platforms) ? wh.platforms : [];
const reqAccountIds = Array.isArray(wh.account_ids) ? wh.account_ids : [];
let contentBase = '';
if (typeof wh.content === 'string' && wh.content.length > 0) contentBase = wh.content;
else if (typeof wh.captions === 'string' && wh.captions.length > 0) contentBase = wh.captions;
else if (wh.captions && typeof wh.captions === 'object' && typeof wh.captions.instagram === 'string') contentBase = wh.captions.instagram;
const title = (typeof wh.title === 'string') ? wh.title : '';
const link = (typeof wh.link === 'string') ? wh.link : '';
let fileIds = Array.isArray(wh.file_ids) ? wh.file_ids : [];
if (fileIds.length === 0 && $json.file_id !== undefined && $json.file_id !== null) fileIds = [$json.file_id];
const reqType = wh.publication_type;
const pubTypeReq = (typeof wh.publish_type === 'string') ? wh.publish_type.trim().toLowerCase() : null;
const tiktokOpts = (wh.tiktok_options && typeof wh.tiktok_options === 'object') ? wh.tiktok_options : {};
const legacyMap = { instagram: 101, youtube: 102, tiktok: 106, threads: 104, x: 105 };
const details = [];
const report = [];
const accountIdSet = {};
for (const rawP of platforms) {
  let p = String(rawP).toLowerCase();
  if (p === 'twitter') p = 'x';
  let content = contentBase;
  if (wh.captions && typeof wh.captions === 'object' && wh.captions[p] !== undefined && wh.captions[p] !== null) content = wh.captions[p];
  const d = {};
  const idx = platforms.indexOf(rawP);
  let accountId = null;
  if (idx >= 0 && idx < reqAccountIds.length && reqAccountIds[idx] !== null && reqAccountIds[idx] !== undefined) accountId = reqAccountIds[idx];
  else if (accByPlatform[p] !== undefined) accountId = accByPlatform[p];
  else if (legacyMap[p] !== undefined) accountId = legacyMap[p];
  if (accountId !== null) { d.account_id = accountId; accountIdSet[accountId] = true; }
  // PM-2: publish_type (post|reels|story) takes priority; else PM-1 logic unchanged
  let effType = null;
  if (pubTypeReq === 'story' && (p === 'instagram' || p === 'facebook')) {
    effType = 2; // STORY
  } else if (pubTypeReq === 'reels') {
    effType = 4; // REELS_SHORTS_CLIPS
  } else if (pubTypeReq === 'post') {
    effType = 1; // POST
  }
  if (effType === null) {
    if (reqType === 1 || reqType === 2 || reqType === 4) {
      effType = reqType;
    } else if (fileIds.length > 0 && (p === 'instagram' || p === 'youtube' || p === 'tiktok' || p === 'rutube')) {
      effType = 4;
    } else {
      effType = 1;
    }
  }
  d.publication_type = effType;
  if (content) d.content = content;
  if (p === 'instagram') {
    if (fileIds.length > 0) d.file_ids = fileIds;
    if (d.publication_type === 4) d.instagram_share_to_feed = true;
  } else if (p === 'youtube') {
    d.youtube_privacy_status = 1;
    if (title) d.title = title;
    if (fileIds.length > 0) d.file_ids = fileIds;
  } else if (p === 'tiktok') {
    if (fileIds.length > 0) d.file_ids = fileIds;
    if (tiktokOpts.comment !== undefined) d.tiktok_comment = !!tiktokOpts.comment;
    if (tiktokOpts.duet !== undefined) d.tiktok_duet = !!tiktokOpts.duet;
    if (tiktokOpts.stitch !== undefined) d.tiktok_stitch = !!tiktokOpts.stitch;
  } else if (p === 'pinterest') {
    if (link) d.link = link;
    if (fileIds.length > 0) d.file_ids = fileIds;
  } else if (p === 'rutube') {
    if (title) d.title = title;
    if (fileIds.length > 0) d.file_ids = fileIds;
  } else if (p === 'ok') {
    if (fileIds.length > 0) d.file_ids = fileIds;
  } else if (p === 'reddit') {
    if (title) d.title = title;
    if (link) d.link = link;
  } else if (p === 'tumblr' || p === 'linkedin') {
    if (title) d.title = title;
  } else if (p === 'facebook') {
    if (fileIds.length > 0) d.file_ids = fileIds;
  }
  details.push(d);
  let r = p + ': type=' + d.publication_type;
  r += (d.account_id !== undefined) ? ' account=' + d.account_id : ' NO_ACCOUNT';
  if (d.file_ids) r += ' files=' + JSON.stringify(d.file_ids);
  if (d.title) r += ' title';
  if (d.link) r += ' link';
  if (d.tiktok_comment !== undefined) r += ' tiktok_comment=' + d.tiktok_comment;
  if (d.tiktok_duet !== undefined) r += ' tiktok_duet=' + d.tiktok_duet;
  if (d.tiktok_stitch !== undefined) r += ' tiktok_stitch=' + d.tiktok_stitch;
  report.push(r);
}
const accountIds = Object.keys(accountIdSet).map(Number);
const postAt = wh.post_at || new Date().toISOString();
return [{ json: {
  details: details,
  account_ids: accountIds,
  file_ids: fileIds,
  post_at: postAt,
  caption: contentBase,
  platforms: platforms,
  publication_type: (pubTypeReq === 'story' ? 2 : pubTypeReq === 'reels' ? 4 : pubTypeReq === 'post' ? 1 : (reqType || (details.length ? details[0].publication_type : 1))),
  generation_id: wh.generation_id,
  account_map: accByPlatform,
  details_report: report
} }];

const wh = $('Webhook').first().json.body || {};
const pub = $json;
let caption = '';
if (wh.content && typeof wh.content === 'string') { caption = wh.content; }
else if (wh.captions) { caption = typeof wh.captions === 'string' ? wh.captions : (wh.captions.instagram ? wh.captions.instagram : JSON.stringify(wh.captions)); }
const postAt = wh.post_at || new Date().toISOString();
const sql = "INSERT INTO posts (client_id, generation_id, cycle_date, caption, target_platforms, postmypost_id, post_at, status) VALUES (1, ?, date('now'), ?, ?, ?, ?, 'pending_publication')";
const params = [wh.generation_id || null, caption, JSON.stringify(wh.platforms || []), pub.id, postAt];
return [{ json: { sql: sql, params: params } }];

let pmId = null;
try { pmId = $('Code mock publication').first().json.id; } catch (e1) { try { pmId = $('HTTP real publication').first().json.id; } catch (e2) { pmId = null; } }
const ins = $('INSERT posts').first().json;
return [{ json: { post_id: ins.lastInsertRowid, postmypost_id: pmId, status: 'pending_publication' } }];

const bd = $('Code build details').first().json;
const accs = ($json.data && Array.isArray($json.data)) ? $json.data : [];
const available = new Set(accs.map(a => (a && a.id != null) ? a.id : null));
let details = Array.isArray(bd.details) ? bd.details : [];
let accountIds = Array.isArray(bd.account_ids) ? bd.account_ids : [];
if (accs.length > 0) {
  details = details.filter(d => available.has(d.account_id));
  accountIds = details.map(d => d.account_id).filter(x => x != null);
}
return [{ json: { ...bd, details: details, account_ids: accountIds, accounts_available: accs.length > 0, accounts_total: accs.length } }];

const bd = $json;
const platforms = Array.isArray(bd.platforms) ? bd.platforms : [];
const details = Array.isArray(bd.details) ? bd.details : [];
const out = [];
for (let i = 0; i < details.length; i++) {
  let p = String((platforms[i] !== undefined && platforms[i] !== null) ? platforms[i] : '').toLowerCase();
  if (p === 'twitter') p = 'x';
  out.push({ json: { ...details[i], platform: p } });
}
return out;

const it = $json;
const caption = (typeof it.content === 'string') ? it.content : '';
const platform = (typeof it.platform === 'string') ? it.platform : '';
return [{ json: { ...it, __prompt: 'base_caption: ' + caption + '\nplatform: ' + platform } }];

const src = $('Code Build prompt').first().json;
const raw = ($json.answer && typeof $json.answer === 'string') ? $json.answer : '';
const m = raw.match(/<CAPTION>([\s\S]*?)<\/CAPTION>/);
let adapted = '';
if (m) adapted = m[1].trim();
if (!adapted && src.content && typeof src.content === 'string') adapted = src.content;
const out = {};
for (const k of Object.keys(src)) {
  if (k !== 'platform' && k !== '__prompt') out[k] = src[k];
}
out.content = adapted;
return [{ json: out }];

const bd = $('Code build details').first().json;
const items = $input.all().map(i => i.json);
if (!Array.isArray(items) || items.length === 0) {
  return [{ json: { ...bd, adapted: false } }];
}
const details = items.map(d => {
  const o = {};
  for (const k of Object.keys(d)) {
    if (k !== 'platform' && k !== '__prompt') o[k] = d[k];
  }
  return o;
});
return [{ json: { ...bd, details: details, adapted: true } }];
